SourceCode.Declaration:
/// <summary>
/// Attribute class made to add extra attributes to the registration collector configuration element
/// </summary>
public class TFMCollectorConfigurationAdditionalAttribute  extends SysAttribute implements SysExtensionIAttribute
{
    str attributeName;
    str value;
}

Method.Source:
void new(str _attributeName, str _value)
{
    super();

    attributeName = _attributeName;
    value = _value;
}

public TFMDocumentContentSubject parmAttributeName(TFMDocumentContentSubject _attributeName = attributeName)
{
    attributeName = _attributeName;

    return attributeName;
}

public TFMDocumentTypeId parmValue(TFMDocumentTypeId _value = value)
{
    value = _value;

    return value;
}
